/// sin(x) on [-pi, pi], Taylor degree 7: x * P(x^2).
template<typename T>
inline auto taylor_sin_7(T x) -> T
{
    const auto x2 = x * x;
    auto p = T(-0.0001984126984126984);
    p = p * x2 + T(0.008333333333333333);
    p = p * x2 + T(-0.16666666666666666);
    p = p * x2 + T(1.0);
    return x * p;
}

