/// sin(x) on [-pi, pi], Taylor degree 7: x * P(x^2).
template<typename T>
inline auto taylor_sin_7(T x) -> T
{
    const auto x2 = x * x;                 // u = x^2
    auto p = T(-0.0001984126984126984);    // -1/7!
    p = p * x2 + T(0.008333333333333333);  //  1/5!
    p = p * x2 + T(-0.16666666666666666);  // -1/3!
    p = p * x2 + T(1.0);                   //  1
    return x * p;
}
